local AviaryKeeper = {}
local PRODUCTS = {
    small_woven_cage = { name = "Majhna pletena kletka", woodCost = 2, ironCost = 1, time = 3, cost = 40, beauty = 18, prestige = 1, happiness = 1, description = "Majhna pletena kletka za pevke." },
    ornate_wooden_aviary = { name = "Izrezljanja kletka", woodCost = 3, ironCost = 1, marbleCost = 1, time = 6, cost = 120, beauty = 35, prestige = 4, happiness = 2, description = "Izrezljana kletka z marmornim podstavkom." },
    brass_bar_aviary = { name = "Medeninasta kletka", ironCost = 3, brassCost = 2, woodCost = 1, time = 9, cost = 280, beauty = 48, prestige = 9, happiness = 3, description = "Kletka z medeninastimi palicami za tujerodne ptice." },
    silver_wire_aviary = { name = "Srebrnatična kletka", ironCost = 2, silverCost = 2, marbleCost = 1, time = 12, cost = 700, beauty = 62, prestige = 16, happiness = 5, description = "Kletka iz srebrne žice za redke ptice." },
    gold_gilded_aviary = { name = "Pozlačena kletka", ironCost = 3, goldCost = 2, silverCost = 1, marbleCost = 2, jewelCost = 1, time = 16, cost = 1500, beauty = 75, prestige = 26, happiness = 7, description = "Pozlačena kletka z dragulji za plemiške ptice." },
    royal_grand_aviary = { name = "Kraljevski veliki ptičnik", woodCost = 6, goldCost = 3, silverCost = 2, marbleCost = 4, jewelCost = 2, pearlCost = 2, time = 23, cost = 3900, beauty = 92, prestige = 58, happiness = 12, description = "Veliki kraljevski ptičnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bird_house = { name = "Ptičja hiša", cost = { gold = 300, wood = 140, stone = 200, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    avian_salon = { name = "Ptičja dvorana", cost = { gold = 1000, wood = 300, stone = 440, marble = 6 }, upkeep = 25, qualityBonus = 18 },
    exotic_atelier = { name = "Egzotični atelje", cost = { gold = 2400, wood = 380, stone = 680, silver = 32, brass = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_aviary_palace = { name = "Kraljevska ptičja palača", cost = { gold = 10800, wood = 600, stone = 1000, gold = 70, jewel = 18 }, upkeep = 215, qualityBonus = 55, prestigeBonus = 50 },
}
AviaryKeeper.woodStock = 16; AviaryKeeper.ironStock = 14; AviaryKeeper.brassStock = 8; AviaryKeeper.marbleStock = 10; AviaryKeeper.silverStock = 8; AviaryKeeper.goldStock = 6; AviaryKeeper.jewelStock = 6; AviaryKeeper.pearlStock = 4
AviaryKeeper.productStock = {}; AviaryKeeper.buildings = {}; AviaryKeeper.maker = nil; AviaryKeeper.activeMaking = {}; AviaryKeeper.totalProducts = 0; AviaryKeeper.dayTimer = 0
function AviaryKeeper.init() AviaryKeeper.woodStock=16; AviaryKeeper.ironStock=14; AviaryKeeper.brassStock=8; AviaryKeeper.marbleStock=10; AviaryKeeper.silverStock=8; AviaryKeeper.goldStock=6; AviaryKeeper.jewelStock=6; AviaryKeeper.pearlStock=4; AviaryKeeper.productStock={}; AviaryKeeper.buildings={}; AviaryKeeper.maker=nil; AviaryKeeper.activeMaking={}; AviaryKeeper.totalProducts=0; AviaryKeeper.dayTimer=0; print("[AviaryKeeper] Royal Aviary Keeper System initialized (6 products, 4 buildings)") end
function AviaryKeeper.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AviaryKeeper.maker={name=n or ("Ptičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ptičar najet: %s (spretnost: %d)",AviaryKeeper.maker.name,s),"success") end; return true end
function AviaryKeeper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AviaryKeeper.build(id) local ok,e=AviaryKeeper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AviaryKeeper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AviaryKeeper.getQualityBonus() local b=0; for _,bd in ipairs(AviaryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AviaryKeeper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and AviaryKeeper.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and AviaryKeeper.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and AviaryKeeper.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.marbleCost and AviaryKeeper.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and AviaryKeeper.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AviaryKeeper.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AviaryKeeper.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AviaryKeeper.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AviaryKeeper.buildings==0 then return false,"Potrebna ptičja hiša" end; if not AviaryKeeper.maker then return false,"Potreben ptičar" end; return true end
function AviaryKeeper.make(pt,qty) qty=qty or 1; local ok,e=AviaryKeeper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then AviaryKeeper.woodStock=AviaryKeeper.woodStock-d.woodCost*qty end; if d.ironCost then AviaryKeeper.ironStock=AviaryKeeper.ironStock-d.ironCost*qty end; if d.brassCost then AviaryKeeper.brassStock=AviaryKeeper.brassStock-d.brassCost*qty end; if d.marbleCost then AviaryKeeper.marbleStock=AviaryKeeper.marbleStock-d.marbleCost*qty end; if d.silverCost then AviaryKeeper.silverStock=AviaryKeeper.silverStock-d.silverCost*qty end; if d.goldCost then AviaryKeeper.goldStock=AviaryKeeper.goldStock-d.goldCost*qty end; if d.jewelCost then AviaryKeeper.jewelStock=AviaryKeeper.jewelStock-d.jewelCost*qty end; if d.pearlCost then AviaryKeeper.pearlStock=AviaryKeeper.pearlStock-d.pearlCost*qty end; local t=d.time; if AviaryKeeper.maker then t=math.max(1,t-math.floor(AviaryKeeper.maker.skill/12)) end; table.insert(AviaryKeeper.activeMaking,{id="aviary_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AviaryKeeper.completeMaking(m) local q=1.0+(AviaryKeeper.getQualityBonus()/100); if AviaryKeeper.maker then q=q+(AviaryKeeper.maker.skill/150) end; q=math.min(2.5,q); AviaryKeeper.productStock[m.productType]=(AviaryKeeper.productStock[m.productType] or 0)+m.quantity; AviaryKeeper.totalProducts=AviaryKeeper.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AviaryKeeper.maker then AviaryKeeper.maker.itemsMade=AviaryKeeper.maker.itemsMade+m.quantity; if math.random()<0.25 then AviaryKeeper.maker.skill=math.min(100,AviaryKeeper.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kletka izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"aviary.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function AviaryKeeper.update(dt) if not _G.state then return end; AviaryKeeper.dayTimer=AviaryKeeper.dayTimer+dt; if AviaryKeeper.dayTimer>=30 then AviaryKeeper.dayTimer=0; for i=#AviaryKeeper.activeMaking,1,-1 do local m=AviaryKeeper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AviaryKeeper.completeMaking(m); table.remove(AviaryKeeper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AviaryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AviaryKeeper.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AviaryKeeper.getStats() return {woodStock=AviaryKeeper.woodStock,ironStock=AviaryKeeper.ironStock,brassStock=AviaryKeeper.brassStock,marbleStock=AviaryKeeper.marbleStock,silverStock=AviaryKeeper.silverStock,goldStock=AviaryKeeper.goldStock,jewelStock=AviaryKeeper.jewelStock,pearlStock=AviaryKeeper.pearlStock,productStock=AviaryKeeper.productStock,numBuildings=#AviaryKeeper.buildings,hasMaker=AviaryKeeper.maker~=nil,makerName=AviaryKeeper.maker and AviaryKeeper.maker.name or "—",makerSkill=AviaryKeeper.maker and AviaryKeeper.maker.skill or 0,activeMaking=#AviaryKeeper.activeMaking,totalProducts=AviaryKeeper.totalProducts} end
return AviaryKeeper
